begin;
select plan(47);

insert into finance.households(id) values ('00000000-0000-4000-8000-00000000e001');
insert into finance.household_members(id,household_id,email,auth_user_id,role) values
 ('00000000-0000-4000-8000-00000000e011','00000000-0000-4000-8000-00000000e001','allocation@test.invalid','00000000-0000-4000-8000-00000000e021','member');
