insert into finance.transaction_treatments(id,household_id,transaction_id,is_transfer,exclude_from_spend,decision_source,status) values ('00000000-0000-4000-8000-00000000e061','00000000-0000-4000-8000-00000000e001','allocation-tx',false,false,'user','confirmed');
