select is(finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-tx')->>'amount_cents','-90000','source cents honor the configured sign');
select is(finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-tx')->>'complete','true','complete source has all required evidence');
select ok(finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-tx')->>'source_fingerprint' is not null,'source snapshot is fingerprinted');
select ok(not has_function_privilege('anon','public.budget_review_allocation_v1(uuid,jsonb)'::regprocedure,'execute'),'anon cannot allocate');

do $$
declare p jsonb; r jsonb; replay jsonb; fp text; rejected boolean:=false;
begin
  select finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-tx')->>'source_fingerprint' into fp;
  p:=jsonb_build_object('transaction_id','allocation-tx','expected_source_fingerprint',fp,'expected_current_set_id',null,'components',jsonb_build_array(jsonb_build_object('amount_cents','-90000','beneficiary_scope','shared','effect_kind','consumption','fund_id','00000000-0000-4000-8000-00000000e071')),'evidence',jsonb_build_object());
  perform set_config('request.jwt.claims',jsonb_build_object('sub','00000000-0000-4000-8000-00000000e021','role','authenticated','email_verified',true)::text,true); perform set_config('request.jwt.claim.sub','00000000-0000-4000-8000-00000000e021',true); perform set_config('request.jwt.claim.role','authenticated',true); execute 'set local role authenticated';
  r:=public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e101',p); replay:=public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e101',p); raise notice '%',is(replay,r,'member allocation replay returns receipt');
  begin perform public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e102',jsonb_set(p,'{expected_source_fingerprint}','"wrong"')); exception when sqlstate 'P0001' then rejected:=sqlerrm='budget_stale: source fingerprint'; end; raise notice '%',ok(rejected,'changed source fingerprint has exact stale error');
  execute 'reset role'; raise notice '%',is((select count(*) from finance.budget_commands where household_id='00000000-0000-4000-8000-00000000e001'),1::bigint,'rejected command creates no receipt');
end $$;

-- Household, member, category, fund, account, source-state, utility, and
-- active-event boundaries all fail closed before a new allocation is written.
do $$
declare fp text; denied boolean; r jsonb; other_h uuid:='00000000-0000-4000-8000-00000000e002'; other_member uuid:='00000000-0000-4000-8000-00000000e022'; other_account uuid:='00000000-0000-4000-8000-00000000e033'; other_fund uuid:='00000000-0000-4000-8000-00000000e076'; other_category uuid:='00000000-0000-4000-8000-00000000e077'; base jsonb;
begin
  insert into finance.households(id) values(other_h); insert into finance.household_members(id,household_id,email,auth_user_id,role) values(other_member,other_h,'other@test.invalid','00000000-0000-4000-8000-00000000e023','member'); insert into public.accounts(account_id,source_account_id,name,household_id,source_system,currency_code) values(other_account,'allocation-other','Other account',other_h,'test','ZAR'); insert into finance.budget_account_settings(household_id,account_id,owner_scope,included,resource_class,freshness_hours,transaction_sign_convention,sign_evidence,actor_id) values(other_h,other_account,'shared',true,'liquid',24,'outflow_negative','statement',other_member); insert into finance.funds(id,household_id,name,beneficiary_scope,created_by) values(other_fund,other_h,'Other fund','shared',other_member); insert into finance.categories(id,household_id,name,slug) values(other_category,other_h,'Other category','other-category');
  insert into public.transactions(id,account_id,date,occurred_on,details,household_id,source_system,source_is_pending,source_is_archived,amount,currency_code,raw_payload_hash) values('allocation-foreign-source',other_account,now(),current_date,'{}',other_h,'test',false,false,-100,'ZAR','foreign-source');
  perform set_config('request.jwt.claims',jsonb_build_object('sub','00000000-0000-4000-8000-00000000e021','role','authenticated')::text,true); perform set_config('request.jwt.claim.sub','00000000-0000-4000-8000-00000000e021',true); perform set_config('request.jwt.claim.role','authenticated',true); execute 'set local role authenticated'; denied:=false; begin perform public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e135',jsonb_build_object('transaction_id','allocation-foreign-source','expected_source_fingerprint','x','components',jsonb_build_array(jsonb_build_object('amount_cents','-10000','beneficiary_scope','shared','effect_kind','consumption','fund_id','00000000-0000-4000-8000-00000000e071')))); exception when sqlstate 'P0001' then denied:=sqlerrm='budget_forbidden: source transaction'; end; execute 'reset role'; raise notice '%',ok(denied,'foreign household source is forbidden');
  insert into public.transactions(id,account_id,date,occurred_on,details,household_id,source_system,source_is_pending,source_is_archived,amount,currency_code,raw_payload_hash) select 'allocation-boundaries',account_id,date,occurred_on,details,household_id,source_system,false,false,-100,'ZAR','boundaries' from public.transactions where id='allocation-tx'; insert into finance.transaction_classifications(household_id,transaction_id,category_id,decision_source,status) values('00000000-0000-4000-8000-00000000e001','allocation-boundaries','00000000-0000-4000-8000-00000000e041','user','confirmed'); insert into finance.transaction_treatments(household_id,transaction_id,is_transfer,exclude_from_spend,decision_source,status) values('00000000-0000-4000-8000-00000000e001','allocation-boundaries',false,false,'user','confirmed'); select finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-boundaries')->>'source_fingerprint' into fp; base:=jsonb_build_object('transaction_id','allocation-boundaries','expected_source_fingerprint',fp,'components',jsonb_build_array(jsonb_build_object('amount_cents','-10000','beneficiary_scope','shared','effect_kind','consumption','fund_id','00000000-0000-4000-8000-00000000e071')));
  execute 'set local role authenticated'; denied:=false; begin perform public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e136',jsonb_set(base,'{components,0,fund_id}',to_jsonb(other_fund::text))); exception when sqlstate 'P0001' then denied:=sqlerrm='budget_forbidden: fund'; end; execute 'reset role'; raise notice '%',ok(denied,'foreign household fund is forbidden');
  execute 'set local role authenticated'; denied:=false; begin perform public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e137',jsonb_set(base,'{components,0,beneficiary_scope}','"member"'::jsonb)||jsonb_build_object('components',jsonb_build_array(jsonb_build_object('amount_cents','-10000','beneficiary_scope','member','beneficiary_member_id',other_member::text,'effect_kind','consumption','fund_id','00000000-0000-4000-8000-00000000e071')))); exception when sqlstate 'P0001' then denied:=sqlerrm='budget_forbidden: beneficiary member'; end; execute 'reset role'; raise notice '%',ok(denied,'foreign household member is forbidden');
  execute 'set local role authenticated'; denied:=false; begin perform public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e138',jsonb_set(base,'{components,0,category_id}',to_jsonb(other_category::text))||jsonb_build_object('evidence',jsonb_build_object('split_review_reason','foreign category test'))); exception when sqlstate 'P0001' then denied:=sqlerrm='budget_forbidden: category'; end; execute 'reset role'; raise notice '%',ok(denied,'foreign household category is forbidden');
  execute 'set local role authenticated'; denied:=false; begin perform public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e139',jsonb_set(base,'{components,0,payment_account_id}',to_jsonb(other_account::text))); exception when sqlstate 'P0001' then denied:=sqlerrm='budget_invalid: payment account'; end; execute 'reset role'; raise notice '%',ok(denied,'wrong payment account is invalid');
  update public.transactions set source_is_pending=true where id='allocation-boundaries'; select finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-boundaries')->>'source_fingerprint' into fp; execute 'set local role authenticated'; denied:=false; begin perform public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e140',jsonb_set(base,'{expected_source_fingerprint}',to_jsonb(fp))); exception when sqlstate 'P0001' then denied:=sqlerrm='budget_incomplete: source'; end; execute 'reset role'; raise notice '%',ok(denied,'pending source is blocked'); update public.transactions set source_is_pending=false,source_is_archived=true where id='allocation-boundaries'; select finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-boundaries')->>'source_fingerprint' into fp; execute 'set local role authenticated'; denied:=false; begin perform public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e141',jsonb_set(base,'{expected_source_fingerprint}',to_jsonb(fp))); exception when sqlstate 'P0001' then denied:=sqlerrm='budget_incomplete: source'; end; execute 'reset role'; raise notice '%',ok(denied,'archived source is blocked'); execute 'reset role';
  update public.transactions set source_is_archived=false where id='allocation-boundaries'; select finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-boundaries')->>'source_fingerprint' into fp; execute 'set local role authenticated'; denied:=false; begin perform public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e142',(base-'transaction_id')||jsonb_build_object('utility_entry_id','00000000-0000-4000-8000-00000000e099')); exception when sqlstate 'P0001' then denied:=sqlerrm='budget_forbidden: utility source'; end; execute 'reset role'; raise notice '%',ok(denied,'unknown utility source is forbidden at the API gate');
  execute 'set local role authenticated'; denied:=false; begin perform public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e144',base||jsonb_build_object('utility_entry_id','00000000-0000-4000-8000-00000000e099')); exception when sqlstate 'P0001' then denied:=sqlerrm='budget_invalid: exactly one source'; end; execute 'reset role'; raise notice '%',ok(denied,'transaction and utility sources cannot be supplied together');
  insert into public.transactions(id,account_id,date,occurred_on,details,household_id,source_system,source_is_pending,source_is_archived,amount,currency_code,raw_payload_hash) select 'allocation-active-event',account_id,date,occurred_on,details,household_id,source_system,false,false,-100,'ZAR','active-event' from public.transactions where id='allocation-tx'; insert into finance.financial_events(id,household_id,event_type,status) values('00000000-0000-4000-8000-00000000e084','00000000-0000-4000-8000-00000000e001','purchase','proposed'); insert into finance.financial_event_legs(id,household_id,event_id,transaction_id,leg_role,status) values('00000000-0000-4000-8000-00000000e085','00000000-0000-4000-8000-00000000e001','00000000-0000-4000-8000-00000000e084','allocation-active-event','economic_recognition','active'); select finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-active-event')->>'source_fingerprint' into fp; execute 'set local role authenticated'; denied:=false; begin perform public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e143',jsonb_build_object('transaction_id','allocation-active-event','expected_source_fingerprint',fp,'components',jsonb_build_array(jsonb_build_object('amount_cents','-10000','beneficiary_scope','shared','effect_kind','consumption','fund_id','00000000-0000-4000-8000-00000000e071')),'decision_update',jsonb_build_object('category_id','00000000-0000-4000-8000-00000000e041','is_transfer',false,'exclude_from_spend',false))); exception when sqlstate 'P0001' then denied:=sqlerrm='budget_incomplete: event review'; end; execute 'reset role'; raise notice '%',ok(denied and not exists(select 1 from finance.transaction_classifications where transaction_id='allocation-active-event') and not exists(select 1 from finance.transaction_treatments where transaction_id='allocation-active-event'),'active event blocks decision update before legacy RPCs');
end $$;

-- The audited category/treatment setters run inside the allocation transaction.
do $$
declare fp text; p jsonb; r jsonb;
begin
  insert into public.transactions(id,account_id,date,occurred_on,details,household_id,source_system,source_is_pending,source_is_archived,amount,currency_code,raw_payload_hash) values('allocation-decision','00000000-0000-4000-8000-00000000e031',now(),current_date,'{}','00000000-0000-4000-8000-00000000e001','test',false,false,-100,'ZAR','decision-hash');
  select finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-decision')->>'source_fingerprint' into fp;
  p:=jsonb_build_object('transaction_id','allocation-decision','expected_source_fingerprint',fp,'components',jsonb_build_array(jsonb_build_object('amount_cents','-10000','beneficiary_scope','shared','effect_kind','consumption','fund_id','00000000-0000-4000-8000-00000000e071')),'evidence',jsonb_build_object(),'decision_update',jsonb_build_object('category_id','00000000-0000-4000-8000-00000000e041','is_transfer',false,'exclude_from_spend',false,'nature',null));
  perform set_config('request.jwt.claims',jsonb_build_object('sub','00000000-0000-4000-8000-00000000e021','role','authenticated','email_verified',true)::text,true); perform set_config('request.jwt.claim.sub','00000000-0000-4000-8000-00000000e021',true); perform set_config('request.jwt.claim.role','authenticated',true); execute 'set local role authenticated'; r:=public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e114',p); execute 'reset role';
  raise notice '%',ok(r->>'set_id' is not null and exists(select 1 from finance.transaction_classifications where transaction_id='allocation-decision' and status='confirmed') and exists(select 1 from finance.transaction_treatments where transaction_id='allocation-decision' and status='confirmed'),'atomic decision update records audited confirmed decisions');
end $$;

-- Source normalization must not manufacture an amount when the account evidence
-- becomes unsuitable. These checks are privileged setup checks, before RPC role.
do $$
declare s jsonb;
begin
  update public.transactions set currency_code='EUR' where id='allocation-tx';
  s:=finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-tx');
  raise notice '%',is(s->'amount_cents','null'::jsonb,'foreign currency has no normalized cents');
  update public.transactions set currency_code='ZAR',amount=-900.001 where id='allocation-tx';
  s:=finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-tx');
  raise notice '%',is(s->'amount_cents','null'::jsonb,'sub-cent source has no normalized cents');
  update public.transactions set amount=-900 where id='allocation-tx';
  update finance.budget_account_settings set transaction_sign_convention='unknown',sign_evidence=null where household_id='00000000-0000-4000-8000-00000000e001' and account_id='00000000-0000-4000-8000-00000000e031';
  s:=finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-tx');
  raise notice '%',is(s->'amount_cents','null'::jsonb,'unknown sign has no normalized cents');
  update finance.budget_account_settings set transaction_sign_convention='outflow_negative',sign_evidence='statement' where household_id='00000000-0000-4000-8000-00000000e001' and account_id='00000000-0000-4000-8000-00000000e031';
end $$;

-- A linked refund must retain the original fund and a mixed split needs receipt
-- evidence.  The source rows are separate so rejected work leaves no receipt.
do $$
declare fp text; p jsonb; r jsonb; original uuid; rejected boolean:=false;
begin
  insert into public.transactions(id,account_id,date,occurred_on,details,household_id,source_system,source_is_pending,source_is_archived,amount,currency_code,raw_payload_hash) values
   ('allocation-refund','00000000-0000-4000-8000-00000000e031',now(),current_date,'{}','00000000-0000-4000-8000-00000000e001','test',false,false,200,'ZAR','refund-hash'),
   ('allocation-mixed','00000000-0000-4000-8000-00000000e031',now(),current_date,'{}','00000000-0000-4000-8000-00000000e001','test',false,false,-900,'ZAR','mixed-hash');
  insert into finance.transaction_classifications(household_id,transaction_id,category_id,decision_source,status) values
   ('00000000-0000-4000-8000-00000000e001','allocation-refund','00000000-0000-4000-8000-00000000e041','user','confirmed'),
   ('00000000-0000-4000-8000-00000000e001','allocation-mixed','00000000-0000-4000-8000-00000000e041','user','confirmed');
  insert into finance.transaction_treatments(household_id,transaction_id,is_transfer,exclude_from_spend,decision_source,status) values
   ('00000000-0000-4000-8000-00000000e001','allocation-refund',false,false,'user','confirmed'),
   ('00000000-0000-4000-8000-00000000e001','allocation-mixed',false,false,'user','confirmed');
  select id into original from finance.budget_allocations where set_id=(select id from finance.budget_allocation_sets where transaction_id='allocation-tx' and status='current');
  select finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-refund')->>'source_fingerprint' into fp;
  p:=jsonb_build_object('transaction_id','allocation-refund','expected_source_fingerprint',fp,'components',jsonb_build_array(jsonb_build_object('amount_cents','20000','beneficiary_scope','shared','effect_kind','refund','fund_id','00000000-0000-4000-8000-00000000e071','original_refund_allocation_id',original::text)),'evidence',jsonb_build_object());
  perform set_config('request.jwt.claims',jsonb_build_object('sub','00000000-0000-4000-8000-00000000e021','role','authenticated','email_verified',true)::text,true); perform set_config('request.jwt.claim.sub','00000000-0000-4000-8000-00000000e021',true); perform set_config('request.jwt.claim.role','authenticated',true); execute 'set local role authenticated';
  r:=public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e111',p); raise notice '%',is(r->>'revision_number','1','linked 20000 refund is recorded');
  execute 'reset role'; select finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-mixed')->>'source_fingerprint' into fp;
  execute 'set local role authenticated';
  begin perform public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e112',jsonb_build_object('transaction_id','allocation-mixed','expected_source_fingerprint',fp,'components',jsonb_build_array(jsonb_build_object('amount_cents','-110000','beneficiary_scope','shared','effect_kind','consumption','fund_id','00000000-0000-4000-8000-00000000e071'),jsonb_build_object('amount_cents','20000','beneficiary_scope','shared','effect_kind','income')),'evidence',jsonb_build_object())); exception when sqlstate 'P0001' then rejected:=sqlerrm='budget_invalid: mixed split receipt'; end;
  raise notice '%',ok(rejected,'mixed signs require a receipt reference'); execute 'reset role';
  raise notice '%',is((select count(*) from finance.budget_commands where command_id='00000000-0000-4000-8000-00000000e112'),0::bigint,'rejected mixed split has no receipt');
end $$;

-- Transfer and mirror evidence retain the source amount but cannot create a fund
-- claim. This is the no-fund zero-effect contract.
do $$
declare fp text; p jsonb; r jsonb;
begin
  insert into public.transactions(id,account_id,date,occurred_on,details,household_id,source_system,source_is_pending,source_is_archived,amount,currency_code,raw_payload_hash) values('allocation-transfer','00000000-0000-4000-8000-00000000e031',now(),current_date,'{}','00000000-0000-4000-8000-00000000e001','test',false,false,-900,'ZAR','transfer-hash');
  insert into finance.transaction_classifications(household_id,transaction_id,category_id,decision_source,status) values('00000000-0000-4000-8000-00000000e001','allocation-transfer','00000000-0000-4000-8000-00000000e041','user','confirmed');
  insert into finance.transaction_treatments(household_id,transaction_id,is_transfer,exclude_from_spend,decision_source,status) values('00000000-0000-4000-8000-00000000e001','allocation-transfer',true,true,'user','confirmed');
  select finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-transfer')->>'source_fingerprint' into fp;
  p:=jsonb_build_object('transaction_id','allocation-transfer','expected_source_fingerprint',fp,'components',jsonb_build_array(jsonb_build_object('amount_cents','-90000','beneficiary_scope','shared','effect_kind','movement')),'evidence',jsonb_build_object());
  perform set_config('request.jwt.claims',jsonb_build_object('sub','00000000-0000-4000-8000-00000000e021','role','authenticated','email_verified',true)::text,true); perform set_config('request.jwt.claim.sub','00000000-0000-4000-8000-00000000e021',true); perform set_config('request.jwt.claim.role','authenticated',true); execute 'set local role authenticated'; r:=public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e113',p); raise notice '%',is(r->>'revision_number','1','nonzero transfer movement is a no-fund allocation'); execute 'reset role';
end $$;

-- Retired funds cannot receive a new source outflow, but remain valid for a
-- correction of their own live history and for linked refunds.
do $$
declare fp text; r jsonb; denied boolean:=false; live uuid; retired uuid:='00000000-0000-4000-8000-00000000e074'; new_retired uuid:='00000000-0000-4000-8000-00000000e075';
begin
  insert into finance.funds(id,household_id,name,beneficiary_scope,created_by) values(retired,'00000000-0000-4000-8000-00000000e001','Retired','shared','00000000-0000-4000-8000-00000000e011');
  insert into finance.funds(id,household_id,name,beneficiary_scope,created_by,status) values(new_retired,'00000000-0000-4000-8000-00000000e001','Retired new','shared','00000000-0000-4000-8000-00000000e011','retired');
  insert into public.transactions(id,account_id,date,occurred_on,details,household_id,source_system,source_is_pending,source_is_archived,amount,currency_code,raw_payload_hash) select 'allocation-retired-new',account_id,date,occurred_on,details,household_id,source_system,false,false,-100,'ZAR','retired-new' from public.transactions where id='allocation-tx';
