-- A correction supersedes the live set as a whole, but prior components and
-- labels stay immutable; old command ids continue to return the old receipt.
do $$
declare old_set uuid; old_alloc uuid; old_label text; fp text; r jsonb; old_result jsonb; old_payload jsonb; current_set uuid;
begin
  select id into old_set from finance.budget_allocation_sets where transaction_id='allocation-tx' and status='current'; select id,category_name_snapshot into old_alloc,old_label from finance.budget_allocations where set_id=old_set;
  select finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-tx')->>'source_fingerprint' into fp; update finance.categories set name='Gifts renamed' where id='00000000-0000-4000-8000-00000000e041'; update public.transactions set raw_payload_hash='allocation-hash-correction' where id='allocation-tx'; select finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-tx')->>'source_fingerprint' into fp;
  perform set_config('request.jwt.claims',jsonb_build_object('sub','00000000-0000-4000-8000-00000000e021','role','authenticated')::text,true); perform set_config('request.jwt.claim.sub','00000000-0000-4000-8000-00000000e021',true); perform set_config('request.jwt.claim.role','authenticated',true); execute 'set local role authenticated'; r:=public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e126',jsonb_build_object('transaction_id','allocation-tx','expected_source_fingerprint',fp,'expected_current_set_id',old_set::text,'components',jsonb_build_array(jsonb_build_object('amount_cents','-90000','beneficiary_scope','shared','effect_kind','consumption','fund_id','00000000-0000-4000-8000-00000000e071')))); execute 'reset role';
  select id into current_set from finance.budget_allocation_sets where transaction_id='allocation-tx' and status='current'; select result,payload into old_result,old_payload from finance.budget_commands where command_id='00000000-0000-4000-8000-00000000e101';
  raise notice '%',ok((select status='superseded' from finance.budget_allocation_sets where id=old_set) and (select category_name_snapshot=old_label from finance.budget_allocations where id=old_alloc) and (select category_name_snapshot='Gifts renamed' from finance.budget_allocations where set_id=current_set),'supersession replaces the whole live set and preserves old components');
  execute 'set local role authenticated'; r:=public.budget_review_allocation_v1(p_command_id => '00000000-0000-4000-8000-00000000e101', p_payload => old_payload); execute 'reset role'; raise notice '%',is(r,old_result,'replaying old command retains old receipt through named API arguments');
end $$;

-- Payload normalization is part of the receipt key.  Optional absent/null keys,
-- trimmed descriptive strings, UUID case, and amount spelling must replay the
