do $$
declare fp text; first_result jsonb; replay jsonb; cmd uuid := '00000000-0000-4000-8000-00000000e115';
begin
  insert into public.transactions(id,account_id,date,occurred_on,details,household_id,source_system,source_is_pending,source_is_archived,amount,currency_code,raw_payload_hash)
  values ('allocation-canonical','00000000-0000-4000-8000-00000000e031',now(),current_date,'{}','00000000-0000-4000-8000-00000000e001','test',false,false,-900,'ZAR','canonical-a');
  insert into finance.transaction_classifications(household_id,transaction_id,category_id,decision_source,status) values ('00000000-0000-4000-8000-00000000e001','allocation-canonical','00000000-0000-4000-8000-00000000e041','user','confirmed');
  insert into finance.transaction_treatments(household_id,transaction_id,is_transfer,exclude_from_spend,decision_source,status) values ('00000000-0000-4000-8000-00000000e001','allocation-canonical',false,false,'user','confirmed');
  select finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-canonical')->>'source_fingerprint' into fp;
  perform set_config('request.jwt.claims',jsonb_build_object('sub','00000000-0000-4000-8000-00000000e021','role','authenticated','email_verified',true)::text,true); perform set_config('request.jwt.claim.sub','00000000-0000-4000-8000-00000000e021',true); perform set_config('request.jwt.claim.role','authenticated',true); execute 'set local role authenticated';
  first_result := public.budget_review_allocation_v1(cmd,jsonb_build_object('transaction_id',' allocation-canonical ','expected_source_fingerprint',' '||fp||' ','components',jsonb_build_array(jsonb_build_object('amount_cents','-090000','beneficiary_scope','shared','effect_kind','consumption','fund_id','00000000-0000-4000-8000-00000000e071','category_name_snapshot',' Gifts '))));
  execute 'reset role'; update public.transactions set raw_payload_hash='canonical-b' where id='allocation-canonical';
  execute 'set local role authenticated'; replay := public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000E115',jsonb_build_object('transaction_id','allocation-canonical','expected_source_fingerprint',fp,'expected_current_set_id',null,'components',jsonb_build_array(jsonb_build_object('amount_cents','-90000','beneficiary_scope','shared','effect_kind','consumption','fund_id','00000000-0000-4000-8000-00000000E071','category_name_snapshot','Gifts','beneficiary_member_id',null,'paid_by_member_id',null,'payment_account_id',null,'original_refund_allocation_id',null,'opening_refund_reason',null,'financial_event_id',null)),'evidence',jsonb_build_object(),'decision_update',null,'classification_id',null,'treatment_id',null)); execute 'reset role';
  raise notice '%',is(replay,first_result,'canonical optional/null payload replay returns exact receipt');
exception when others then execute 'reset role'; raise;
end $$;

-- Structural validation runs before command replay and before any receipt/domain
-- write, including when the command id already has a successful receipt.
do $$
declare p jsonb; denied boolean; before_count bigint; after_count bigint; fp text;
begin
  select finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-canonical')->>'source_fingerprint' into fp;
  p:=jsonb_build_object('transaction_id','allocation-canonical','expected_source_fingerprint',fp,'components',jsonb_build_array(jsonb_build_object('amount_cents','-90000','beneficiary_scope','shared','effect_kind','consumption','fund_id','not-a-uuid')));
  execute 'set local role authenticated'; perform set_config('request.jwt.claims',jsonb_build_object('sub','00000000-0000-4000-8000-00000000e021','role','authenticated')::text,true); perform set_config('request.jwt.claim.sub','00000000-0000-4000-8000-00000000e021',true); perform set_config('request.jwt.claim.role','authenticated',true);
  denied:=false; begin perform public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000E115',p); exception when sqlstate 'P0001' then denied:=sqlerrm='budget_invalid: invalid fund_id'; end; execute 'reset role'; raise notice '%',ok(denied,'malformed UUID is invalid before previous receipt replay');
  p:=jsonb_set(p,'{components,0,fund_id}','"00000000-0000-4000-8000-00000000e071"'); p:=jsonb_set(p,'{components,0,unknown}','true');
  execute 'set local role authenticated'; denied:=false; begin perform public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e116',p); exception when sqlstate 'P0001' then denied:=sqlerrm like 'budget_invalid:%'; end; execute 'reset role'; raise notice '%',ok(denied,'unknown component key is invalid before writes');
  p:=p - 'components' || jsonb_build_object('components',jsonb_build_array(jsonb_build_object('amount_cents','-90000','beneficiary_scope','shared','effect_kind','consumption','fund_id','00000000-0000-4000-8000-00000000e071')),'evidence',jsonb_build_object('not_allowed',true)); execute 'set local role authenticated'; denied:=false; begin perform public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e117',p); exception when sqlstate 'P0001' then denied:=sqlerrm like 'budget_invalid:%'; end; execute 'reset role'; raise notice '%',ok(denied,'unknown evidence key is invalid before writes');
  p:=jsonb_set(p,'{evidence}','{}'::jsonb)||jsonb_build_object('decision_update',jsonb_build_object('category_id','00000000-0000-4000-8000-00000000e041','is_transfer',false,'exclude_from_spend',false,'nature',repeat('x',81))); execute 'set local role authenticated'; denied:=false; begin perform public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e118',p); exception when sqlstate 'P0001' then denied:=sqlerrm='budget_invalid: nature'; end; execute 'reset role'; raise notice '%',ok(denied,'nature over 80 characters is invalid before writes');
  p:=jsonb_set(p,'{decision_update,nature}','1'::jsonb); execute 'set local role authenticated'; denied:=false; begin perform public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e119',p); exception when sqlstate 'P0001' then denied:=sqlerrm like 'budget_invalid: invalid nature'; end; execute 'reset role'; raise notice '%',ok(denied,'wrong decision field type is invalid before writes');
end $$;

-- A failed component check must roll back both audited decision writes and the
-- allocation journal.  Counts are read as admin so RLS cannot hide a rollback.
do $$
declare fp text; p jsonb; denied boolean:=false; c0 bigint; t0 bigint; f0 bigint; r0 bigint; a0 bigint; c1 bigint; t1 bigint; f1 bigint; r1 bigint; a1 bigint;
begin
  insert into public.transactions(id,account_id,date,occurred_on,details,household_id,source_system,source_is_pending,source_is_archived,amount,currency_code,raw_payload_hash) values('allocation-decision-fail','00000000-0000-4000-8000-00000000e031',now(),current_date,'{}','00000000-0000-4000-8000-00000000e001','test',false,false,-100,'ZAR','decision-fail');
  select finance.budget_source_snapshot('00000000-0000-4000-8000-00000000e001','allocation-decision-fail')->>'source_fingerprint' into fp;
  select count(*) into c0 from finance.transaction_classifications where transaction_id='allocation-decision-fail'; select count(*) into t0 from finance.transaction_treatments where transaction_id='allocation-decision-fail'; select count(*) into f0 from finance.classification_feedback where transaction_id='allocation-decision-fail'; select count(*) into r0 from finance.budget_commands; select count(*) into a0 from finance.budget_allocation_sets;
  p:=jsonb_build_object('transaction_id','allocation-decision-fail','expected_source_fingerprint',fp,'components',jsonb_build_array(jsonb_build_object('amount_cents','-9999','beneficiary_scope','shared','effect_kind','consumption','fund_id','00000000-0000-4000-8000-00000000e071')),'decision_update',jsonb_build_object('category_id','00000000-0000-4000-8000-00000000e041','is_transfer',false,'exclude_from_spend',false));
  perform set_config('request.jwt.claims',jsonb_build_object('sub','00000000-0000-4000-8000-00000000e021','role','authenticated')::text,true); perform set_config('request.jwt.claim.sub','00000000-0000-4000-8000-00000000e021',true); perform set_config('request.jwt.claim.role','authenticated',true); execute 'set local role authenticated'; begin perform public.budget_review_allocation_v1('00000000-0000-4000-8000-00000000e120',p); exception when sqlstate 'P0001' then denied:=sqlerrm='budget_invalid: component sum'; end; execute 'reset role';
  select count(*) into c1 from finance.transaction_classifications where transaction_id='allocation-decision-fail'; select count(*) into t1 from finance.transaction_treatments where transaction_id='allocation-decision-fail'; select count(*) into f1 from finance.classification_feedback where transaction_id='allocation-decision-fail'; select count(*) into r1 from finance.budget_commands; select count(*) into a1 from finance.budget_allocation_sets;
  raise notice '%',ok(denied and c0=c1 and t0=t1 and f0=f1 and r0=r1 and a0=a1,'failed decision allocation is atomic across audited decisions and journal');
end $$;


select * from finish();
rollback;
